public class Main {
    public static void main(String[] args) {
        String s = "swiss";
        int[] counts = new int[26];
        for (char c : s.toCharArray()) {
            counts[c - 'a']++;
        }
        int answer = -1;
        for (int i = 0; i < s.length(); i++) {
            if (counts[s.charAt(i) - 'a'] == 1) {
                answer = i;
                break;
            }
        }
        System.out.println(answer);
    }
}
